--
-- Name: v_message_threads; Type: VIEW; Schema: public; Owner: neondb_owner
--

CREATE VIEW public.v_message_threads AS
 SELECT mt.id,
    mt.root_message_id,
    mt.message_id,
    mt.depth,
    mt.path,
    mt.created_at,
    m.sender_id,
    m.content,
    m.edited_content,
    m.created_at AS message_created_at,
    m.context_type,
    m.context_id
   FROM (public.message_threads mt
     JOIN public.messages m ON ((m.id = mt.message_id)))
  WHERE (m.deleted_at IS NULL)
  ORDER BY mt.path;


ALTER VIEW public.v_message_threads OWNER TO neondb_owner;

--
-- Name: v_unread_counts; Type: VIEW; Schema: public; Owner: neondb_owner
--

CREATE VIEW public.v_unread_counts AS
 SELECT mr.recipient_id,
    m.context_type,
    count(*) AS unread_count,
    (((u.first_name)::text || ' '::text) || (u.last_name)::text) AS sendername,
    u.id AS sender_id
   FROM ((public.message_recipients mr
     JOIN public.messages m ON ((m.id = mr.message_id)))
     JOIN public.users u ON ((m.sender_id = (u.id)::text)))
  WHERE ((mr.read = false) AND (m.deleted_at IS NULL) AND (mr.context_access_revoked = false) AND (u.id IS NOT NULL))
  GROUP BY mr.recipient_id, m.context_type, u.id, u.first_name, u.last_name;


ALTER VIEW public.v_unread_counts OWNER TO neondb_owner;

